/* Default: one column, every screen */
.layout {
  display: grid;
  gap: 1rem;
}

/* From 48em (768px at the default font size): two columns */
@media (min-width: 48em) {
  .layout {
    grid-template-columns: 1fr 2fr;
  }
}

/* The same condition in range syntax */
@media (width >= 48em) {
  .layout {
    grid-template-columns: 1fr 2fr;
  }
}

/* Only between two widths */
@media (48em <= width < 80em) {
  .layout {
    gap: 2rem;
  }
}

:root {
  --bg: #ffffff;
  --text: #172033;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f172a;
    --text: #e2e8f0;
  }
}

body {
  background: var(--bg);
  color: var(--text);
}

img,
video {
  max-width: 100%;
  height: auto;
}

.container {
  width: min(100% - 2rem, 70rem);
  margin-inline: auto;
}

h1 {
  font-size: clamp(1.75rem, 1.2rem + 2.5vw, 3rem);
}
